function resetRound(){game.stage=remoteState?.stage||(matchKind==='freekick'?practicePhase:1);game.legendRound=remoteState?.legendRound||1;game.introKey=null;game.totalGoals=0;game.totalShots=0;game.allShots=[];game.stageOverlay=false;game.round++;document.body.dataset.gameKind=matchKind;$('#free-stage').hidden=matchKind!=='freekick';$('#stage-unlocked').hidden=true;game.shots=game.goals=0;game.history=[];$('#goals').textContent='0';$('#shots').textContent='0 / 5';$('#round-over').hidden=true;$('#shot-controls').hidden=false;$('#shot-history').innerHTML=Array.from({length:5},()=>'<i></i>').join('');$('#best').textContent='Recorde neste aparelho: '+game.best+' / 5';prepareShot();}

